WITH fault_counts AS (
  SELECT COUNT(*) AS total_faults FROM gishub.fleet.fault_events
), claim_counts AS (
  SELECT COUNT(DISTINCT event_id) AS claimed_faults FROM gishub.fleet.warranty_claims
)
SELECT
  100.0 * claimed_faults / total_faults AS pct_faults_with_warranty_claim
FROM fault_counts, claim_counts;
